<form method="post" action="<?= e(url('/admin/account/password')) ?>" class="card p-5 md:p-6 max-w-md space-y-3" data-once><?= csrf_field() ?><h2 class="font-bold">Change password</h2><p class="text-sm muted">Signed in as <b><?= e($admin['email']) ?></b> (<?= e($admin['role']) ?>)</p>
<div><label class="label" for="current">Current password</label><input class="input" id="current" type="password" name="current" required autocomplete="current-password"></div><div><label class="label" for="new">New password (min 10 chars)</label><input class="input" id="new" type="password" name="new" required minlength="10" autocomplete="new-password"></div><button class="btn btn-primary">Update password</button></form>
